from __future__ import absolute_import
import os
import os.path
import re

from robot.api import logger
from robot.libraries.BuiltIn import BuiltIn


class QualityLevel(object):
    """

    """

    def add_new_ql(self, ql, comment):
        """
        Keyword for adding new Quality Level to file.

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | ql                 | Yes    | Quality Level to log to file          |
        +--------------------+--------+---------------------------------------+
        | comment            | Yes    | Description why quality level changed |
        +--------------------+--------+---------------------------------------+

        .. warning::
           SWBT - support
        """
        is_new_lower = self.compare_ql(ql)
        path_to_ql_file = os.path.join(
            str(BuiltIn().get_variable_value("${BTSfiles}")),
            "QualityLevel.txt")
        if is_new_lower:
            with open(path_to_ql_file, 'a') as ql_file:
                ql_file.write(
                    "{ql} - {comment} \n".format(ql=ql, comment=comment))
            logger.info("New QL has been added:"
                        " {ql} - {comment}".format(ql=ql, comment=comment))

    def compare_ql(self, new):
        """
        Keyword for comparison of new Quality Level with existing Quality Level

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        +--------------------+-------+----------------------------------------+
        | Input Parameters   | Man.  | Description                            |
        +====================+=======+========================================+
        | new                | Yes   | state to be saved in QualityLevel file |
        +--------------------+-------+----------------------------------------+
        """
        actual = self.get_actual_ql()
        found = re.search('\d', new)
        if not found:
            logger.info("NO RUN or ENV issue occurs")
            return True
        new = found.group()
        if actual >= new and int(new) != 5:
            return True
        return False

    def get_actual_ql(self):
        """
        Keyword for getting last saved Quality Level

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        | **Return value:**
        | parameters from siteconf found by text.
        """
        path_to_ql_file = os.path.join(
            str(BuiltIn().get_variable_value("${BTSfiles}")),
            "QualityLevel.txt")
        with open(path_to_ql_file, 'r') as ql_file:
            ql_file = ql_file.readlines()[-1]
            found = re.search('(?<=QL)\d', ql_file)
            if found:
                return found.group()
            return ql_file.split()[0]
